// Package game contains the Dyna Blaster program: the game logic,
// translated from the original 1992 machine code into Go (files dyna_*.go,
// generated by cmd/x86gen), together with the original data files.
package game

import (
	"embed"
	"io/fs"
	"path"
	"strings"

	. "dynablaster/machine"
)

//go:embed data
var dataFS embed.FS

// Storage persists files written by the game (the DYNA.CFG setup file).
type Storage interface {
	Load(name string) ([]byte, bool)
	Save(name string, data []byte)
}

type gameFS struct{ st Storage }

func (g gameFS) ReadFile(name string) ([]byte, bool) {
	name = strings.ToUpper(strings.ReplaceAll(name, "\\", "/"))
	if g.st != nil {
		if b, ok := g.st.Load(name); ok {
			return b, true
		}
	}
	b, err := fs.ReadFile(dataFS, path.Join("data", name))
	if err != nil {
		return nil, false
	}
	return b, true
}

func (g gameFS) WriteFile(name string, data []byte) {
	if g.st != nil {
		g.st.Save(strings.ToUpper(strings.ReplaceAll(name, "\\", "/")), data)
	}
}

// Options controls how the program runs.
type Options struct {
	Storage Storage
	// Interpret disables the translated code (reference interpreter only).
	Interpret bool
}

// New creates a machine with the game loaded and ready to run.
func New(opt Options) *M {
	m := NewMachine()
	m.DOS.FS = gameFS{opt.Storage}
	img, err := dataFS.ReadFile("data/dyna.img")
	if err != nil {
		panic(err)
	}
	m.LoadSnapshot(Lin(dynaPSP+0x10, 0), img, dynaPSP)
	m.S[CS], m.IP = dynaCS, dynaIP
	m.S[SS], m.R[SP] = dynaSS, dynaSP
	m.S[DS], m.S[ES] = dynaPSP, dynaPSP
	m.Flags = 0x0202
	if !opt.Interpret {
		m.Register(dynaBlocks)
	}
	return m
}
